using UnityEngine;

// 3인칭 산책: 리지드바디 3D로 걸어서 건물 · 가로등에 막혀요.
// 쓰인 코드: GetComponent<Rigidbody>() · velocity · isGrounded · Input.GetAxis("Mouse X") · Mathf.LerpAngle · LookAt
// WASD · 방향키: 카메라 기준으로 걷기 · Shift: 달리기 · Space: 점프
// 마우스를 누른 채 끌거나 Q · E: 카메라를 주인공 둘레로 돌리기
public class StreetWalker : MonoBehaviour
{
    [Header("이동")]
    public float walkSpeed = 3.5f;
    public float runSpeed = 7f;
    public float jumpPower = 5.5f;
    [Tooltip("몸을 돌리는 빠르기")]
    public float turnSmooth = 12f;

    [Header("카메라")]
    public float cameraDistance = 5.5f;
    public float cameraHeight = 2.4f;
    public float mouseSensitivity = 3f;
    public float keyTurnSpeed = 120f;

    Rigidbody rb;
    Transform cam;
    float yaw;
    Vector3 startPos;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
        if (transform.childCount > 0) cam = transform.GetChild(0);
        yaw = transform.eulerAngles.y;
        startPos = transform.position;
    }

    void Update()
    {
        // 카메라 돌리기
        if (Input.GetMouseButton(0) || Input.GetMouseButton(1)) yaw += Input.GetAxis("Mouse X") * mouseSensitivity;
        if (Input.GetKey(KeyCode.Q)) yaw -= keyTurnSpeed * Time.deltaTime;
        if (Input.GetKey(KeyCode.E)) yaw += keyTurnSpeed * Time.deltaTime;

        // 카메라가 보는 쪽을 기준으로 걷기
        float r = yaw * Mathf.Deg2Rad;
        Vector3 forward = new Vector3(Mathf.Sin(r), 0, Mathf.Cos(r));
        Vector3 right = new Vector3(Mathf.Cos(r), 0, -Mathf.Sin(r));
        Vector3 move = right * Input.GetAxisRaw("Horizontal") + forward * Input.GetAxisRaw("Vertical");
        float speed = Input.GetKey(KeyCode.LeftShift) ? runSpeed : walkSpeed;
        if (move.magnitude > 0.01f)
        {
            move = move.normalized;
            float face = Mathf.Atan2(move.x, move.z) * Mathf.Rad2Deg;
            transform.eulerAngles = new Vector3(0, Mathf.LerpAngle(transform.eulerAngles.y, face, turnSmooth * Time.deltaTime), 0);
        }
        Vector3 v = rb.velocity;
        rb.velocity = new Vector3(move.x * speed, v.y, move.z * speed);   // 위아래(y)는 중력에 맡겨요

        // 혹시 바닥 밖으로 떨어지면 처음 자리로
        if (transform.position.y < -5f)
        {
            transform.position = startPos;
            rb.velocity = Vector3.zero;
        }

        // 점프 (땅에 닿아 있을 때만)
        if (rb.isGrounded && Input.GetButtonDown("Jump")) rb.velocity = new Vector3(rb.velocity.x, jumpPower, rb.velocity.z);

        // 카메라 따라가기
        if (cam != null)
        {
            Vector3 target = transform.position + new Vector3(0, 1.1f, 0);
            cam.position = target - forward * cameraDistance + new Vector3(0, cameraHeight - 1.1f, 0);
            cam.LookAt(target);
        }
    }
}

using UnityEngine;

// 반딧불: 주인공이 닿으면 하나 모으고 사라져요. 제자리에서 둥실둥실 떠 있어요.
// 쓰인 코드: OnTriggerEnter(Collider) · other.tag · Inventory.Add · UIScreen.SetText · UIScreen.Show · Mathf.Sin
public class Firefly : MonoBehaviour
{
    public int goal = 6;          // 모두 모아야 하는 반딧불 수
    public float bob = 0.25f;     // 떠오르는 높이

    float baseY;
    float t;

    void Start()
    {
        baseY = transform.position.y;
        t = transform.position.z;     // 반딧불마다 박자가 조금씩 달라요
    }

    void Update()
    {
        t += Time.deltaTime * 2.5f;
        Vector3 p = transform.position;
        transform.position = new Vector3(p.x, baseY + Mathf.Sin(t) * bob, p.z);
    }

    void OnTriggerEnter(Collider other)
    {
        if (other.tag != "Player") return;
        int total = Inventory.Add("반딧불", 1);
        Sfx("반딧불");
        UIScreen.SetText("길 안내", "개수", "반딧불 " + total + " / " + goal);
        if (total >= goal)
        {
            UIScreen.Show("완료");
            Sfx("완료 팡파르");
        }
        gameObject.SetActive(false);
    }

    // ▼ 직접 만든 메서드: 씬의 「효과음」 오브젝트에 붙은 오디오 소스로 이름이 같은 오디오 클립을 겹쳐 재생해요
    //   PlayOneShot("클립 이름")은 지금 나는 소리를 끊지 않고 하나 더 겹쳐서 틀어요
    void Sfx(string clip)
    {
        GameObject.Find("효과음").GetComponent<AudioSource>().PlayOneShot(clip);
    }
}
